public void processPO(MET_POReceiptWorkerContract _contract)
{
    PurchTable purchTable;
    PackingSlipId packingSlipId;
    VendPackingSlipJour vendpackingslipjour;
    container purchIds = _contract.parmPurchIds();
    int i;
    int startLine = infologLine();
    Map PurchMap;

    for (i = 1; i <= conLen(purchIds); i++)
    {
        PurchMap = new Map(Types::Int64, Types::String);
        info(strFmt("@MET:METPOReceiptInfo", i, conLen(purchIds), conPeek(purchIds, i)));
        try
        {
            ttsbegin;

            purchTable = PurchTable::find(conPeek(purchIds, i), true);

            select count(RecId) from vendpackingslipjour
                where vendpackingslipjour.PurchId == purchTable.PurchId;

            packingSlipId = strFmt('%1-%2', purchTable.PurchId, vendpackingslipjour.RecId + 1);
            PurchMap.insert(purchTable.RecId, packingSlipId);

            if (purchTable.RecId)
            {
                this.postReceipt(purchMap);
            }
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            info(strFmt("@MET:METPOReceiptDeadLockErr", conPeek(purchIds, i)));
        }
         catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                info(strFmt("@MET:METPOReceiptConflictErr", conPeek(purchIds, i)));
                continue;
            }
            else
            {
                throw;
            }
        }
        catch (Exception::Error)
        {
            int errLine;
            int endLine = infologLine();
            str errMsg;
            for (errLine = startLine + 1; errLine <= endLine; errLine++)
            {
                str errorMessage = SysInfologMessageStruct::construct(infolog.text(errLine)).message();
                errMsg += errorMessage + "\n";
                // Log or display the extracted message
            }
            info(strFmt("@MET:METPOReceiptErr", conPeek(purchIds, i), errMsg));
        }
    }
}

private void postReceipt(Map _purchMap)
{
    PurchFormLetter_PackingSlip purchPackingSlip = PurchFormLetter::construct(DocumentStatus::PackingSlip);
    PurchFormletterParmData  parmData = PurchFormletterParmData::newData(DocumentStatus::PackingSlip);
    PurchParmUpdate parmUpdate;
    PurchParmTable purchParmTable;
    PurchParmLine purchParmLine;
    PurchLine purchLine;
    MapEnumerator mapEnum = _purchMap.getEnumerator();
    PurchTable purchTable;

    mapEnum.moveNext();
    purchTable  = PurchTable::findRecId(mapEnum.current());

    //create parm data
    parmData.parmOnlyCreateParmUpdate(true);
    parmData.createData(false);
    parmUpdate = parmData.parmParmUpdate();

    //create purch parm table
    purchParmTable.clear();
    purchparmTable.Ordering = Documentstatus::PackingSlip;
    PurchParmTable.ParmJobStatus = ParmJobStatus::Waiting;
    purchParmTable.PurchId = purchTable.PurchId;
    purchParmTable.PurchName = purchTable.PurchName;
    purchParmTable.OrderAccount    = purchTable.OrderAccount;
    purchParmTable.InvoiceAccount = purchTable.InvoiceAccount;
    purchParmTable.CurrencyCode = purchTable.CurrencyCode;
    purchParmTable.DeliveryName = purchTable.DeliveryName;
    purchParmTable.DeliveryPostalAddress = purchTable.DeliveryPostalAddress;
    purchParmTable.Num = mapEnum.currentValue();
    purchParmTable.DocumentNum = mapEnum.currentValue();
    purchParmTable.ParmId = parmUpdate.ParmId;
    purchParmTable.TransDate = systemDateGet();
    purchParmTable.DocumentDate = systemDateGet();
    purchparmtable.insert();

    while select PurchLine where PurchLine.purchid == purchTable.PurchId
    {
        //create purch parm line
        purchParmLine.clear();
        purchParmLine.initFromPurchLine(PurchLine);
        purchParmLine.ReceiveNow = PurchLine.RemainPurchPhysical;
        purchParmLine.ParmId = parmUpdate.ParmId;
        purchParmLine.TableRefId = purchParmTable.TableRefId;
        purchParmLine.setQty(DocumentStatus::PackingSlip, false, true, true);
        purchParmLine.setLineAmount();
        purchParmLine.insert();
    }

    purchpackingslip.transDate(systemDateGet());
    purchPackingSlip.proforma(false);
    purchPackingSlip.specQty(PurchUpdate::All);
    purchPackingSlip.purchTable(PurchTable::find(purchTable.PurchId));
    purchPackingSlip.parmParmTableNum(parmUpdate.ParmId);
    purchPackingSlip.purchParmUpdate(parmUpdate);
    purchPackingSlip.run();

}
